static func _poly_point(poly: Array, s: float) -> Vector2:
	if poly.is_empty():
		return Vector2.ZERO
	var left := maxf(0.0, s)
	for i in range(1, poly.size()):
		var a: Vector2 = poly[i - 1]
		var b: Vector2 = poly[i]
		var l := a.distance_to(b)
		if left <= l:
			return a + (b - a) * (left / maxf(l, 0.000001))
		left -= l
	return poly[-1]

